import { NextResponse } from "next/server";
import { enqueuePdfJob } from "@/lib/rabbitmq"; // ya "../lib/rabbitmq" agar alias nahi hai

export async function POST() {
  try {
    const id = "job-" + Date.now();

    await enqueuePdfJob({
      id,
      payload: {} // abhi /api/pdf khud data.json se lega
    });

    console.log("✅ Enqueued job via /api/enqueue-pdf:", id);

    return NextResponse.json({ ok: true, jobId: id });
  } catch (err) {
    console.error("❌ enqueue-pdf error:", err);
    return NextResponse.json({ ok: false }, { status: 500 });
  }
}
